select row.* from placements join configs on idx=(p->>4)::int cross join lateral jsonb_populate_record(null::public.menu_offerings, configs.value || jsonb_build_object('id',p->0,'menu_service_id',p->1,'last_seen_at',p->2,'sort_order',p->3)) row;

insert into public.food_items select * from seed_food_items on conflict do nothing;
-- Existing catalog versions may already carry the same food's reviews.
update seed_food_versions v set food_item_id=i.id from seed_food_items seed
join public.food_items i using(source_namespace,source_item_id) where v.food_item_id=seed.id;
insert into public.food_versions select * from seed_food_versions on conflict do nothing;

-- Resolve café IDs by their source slugs on installations with prior imports.
update seed_stations s set cafe_id=c.id from public.cafes c where c.source_key=s.source_key;
update seed_menu_services s set cafe_id=k.cafe_id from seed_stations k
where s.cafe_id=md5('scu:cafe:'||k.source_key)::uuid;
insert into public.stations select * from seed_stations on conflict do nothing;
insert into public.menu_services select * from seed_menu_services on conflict do nothing;
update seed_menu_offerings o set food_version_id=v.id from seed_food_versions seed
join public.food_versions v using(food_item_id,content_hash) where o.food_version_id=seed.id;
update seed_menu_offerings o set station_id=k.id, cafe_id=k.cafe_id from seed_stations seed
join public.stations k using(cafe_id,source_key) where o.station_id=seed.id;
update seed_menu_offerings o set menu_service_id=s.id from seed_menu_services seed
join public.menu_services s using(cafe_id,service_date,source_key) where o.menu_service_id=seed.id;
insert into public.menu_offerings select * from seed_menu_offerings on conflict do nothing;

commit;
